"""Verify independent PR and deferred patches at the two locally available commits."""
import hashlib,io,json,re,shutil,subprocess,tarfile
from functools import lru_cache
from prepare import ROOT,A,H
from layout import REPO,COMMIT,DEVELOP,PR_COMMIT,UPSTREAM_REPO
from run import execute,ENV

FILES=['reader.rs','writer.rs','values.rs','macros.rs']

@lru_cache(maxsize=1)
def formatter():
    name='nightly-2026-06-01'
    version=subprocess.check_output(['rustfmt','+'+name,'--version'],text=True).strip()
    config=next((REPO/p for p in ['rustfmt.toml','.rustfmt.toml'] if (REPO/p).exists()),A/'rustfmt-default.toml')
    record={'provenance':H,'toolchain':name,'version':version,'edition':'2024',
            'repository_pin':'nightly-2026-06-03','settings':'repository settings' if config.parent==REPO else 'default','result':'PASS'}
    (A/'evidence/gen/rustfmt-version.json').write_text(json.dumps(record,indent=2)+'\n')
    return ['rustfmt','+'+name,'--edition','2024','--config-path',str(config)]

def format_source(source):
    return subprocess.run([*formatter(),'--emit','stdout'],input=source,text=True,capture_output=True,check=True,cwd=ROOT).stdout

def archive_source(commit,dest):
    if dest.exists(): shutil.rmtree(dest)
    dest.mkdir(parents=True)
    data=subprocess.check_output(['git','-C',str(UPSTREAM_REPO),'archive',commit,'libraries/cbor'])
    with tarfile.open(fileobj=io.BytesIO(data)) as archive:
        for member in archive:
            if member.isfile():
                path=dest/member.name
                path.parent.mkdir(parents=True,exist_ok=True)
                path.write_bytes(archive.extractfile(member).read())

def check():
    from final_pr import check_receipts
    check_receipts()
    records=[]
    for ref,commit in [('subject',COMMIT),('develop',DEVELOP)]:
        actual=subprocess.check_output(['git','-C',str(UPSTREAM_REPO),'rev-parse',commit],text=True).strip()
        assert actual==commit
        for label,count in [('upstream',10),('deferred',4)]:
            patch=A/(label+'-tests.patch')
            added='\n'.join(line[1:] for line in patch.read_text().splitlines() if line.startswith('+') and not line.startswith('+++'))
            names=re.findall(r'^\s*fn (test_\w+)\(',added,re.M)
            attrs=re.findall(r'^\s*#\[test\]',added,re.M)
            assert len(names)==len(set(names))==len(attrs)==count,(label,names)
            assert not re.search(r'#\[test\]\s*#\[test\]',added)
            assert 'generated by Codex' not in added
            if label=='upstream':
                assert not any(name in added for name in ['test_from_','appendix'])
            dest=A/(ref+'-'+label+'-check')
            archive_source(commit,dest)
            execute(['git','-C',dest,'apply','--check',patch],ref+'-'+label+'-apply-check',env={**ENV,'GIT_CEILING_DIRECTORIES':str(dest.parent)})
            execute(['git','-C',dest,'apply',patch],ref+'-'+label+'-apply',env={**ENV,'GIT_CEILING_DIRECTORIES':str(dest.parent)})
            sources=dest/'libraries/cbor/src'
            if label=='upstream':
                blobs=json.loads((A/'evidence/final-pr-2026-10-13/receipt.json').read_text())['source_blobs']
                for file, blob in blobs.items():
                    assert hashlib.sha256((sources/file).read_bytes()).hexdigest()==blob['final_sha256']
            execute([*formatter(),'--check',*[sources/f for f in FILES]],'rustfmt-'+ref+'-'+label)
            p=execute(['cargo','+1.99.0','test','--offline','--manifest-path',dest/'libraries/cbor/Cargo.toml'],ref+'-'+label+'-patch-tests',timeout=60)
            for name in names:
                assert re.search(r'::'+name+r'(?: - should panic)? \.\.\. ok',p.stdout),name
            assert f'{78+count} passed; 0 failed' in p.stdout and '5 passed; 0 failed' in p.stdout
            records.append({'ref':ref,'commit':commit,'patch':patch.name,'added_tests':count,'unit_tests':78+count,'doc_tests':5,'result':'PASS'})
            execute(['git','-C',dest,'apply','--check',A/'upstream-doc.patch'],ref+'-'+label+'-doc-check',env={**ENV,'GIT_CEILING_DIRECTORIES':str(dest.parent)})
    # Independently check the documentation patch at pristine commits.
    for ref,commit in [('subject',COMMIT),('develop',DEVELOP)]:
        dest=A/(ref+'-doc-check'); archive_source(commit,dest)
        execute(['git','-C',dest,'apply','--check',A/'upstream-doc.patch'],ref+'-doc-apply-check',env={**ENV,'GIT_CEILING_DIRECTORIES':str(dest.parent)})
    record={'provenance':H,'develop_commit':DEVELOP,'source':'locally available commit; no network',
            'pr_test_count':10,'pr_commit':PR_COMMIT,'deferred_test_count':4,'checks':records,
            'duplicate_finding':'Earlier duplicated #[test] allegation was a review error: 19 missing cases plus one Appendix test.',
            'doc_patch':'Two documentation mismatches; no code changes; applies independently and after either test patch.',
            'rustfmt':json.loads((A/'evidence/gen/rustfmt-version.json').read_text()),'result':'PASS'}
    (A/'evidence/gen/upstream-review.json').write_text(json.dumps(record,indent=2)+'\n')
    print('UPSTREAM: PR 10 tests; deferred 4 tests; rustfmt and both commits PASS',flush=True)

